const command="@(Get-CimInstance Win32_Process -Filter \"Name = 'Agentopia.exe'\" | Where-Object { $_.CommandLine -notmatch '--type=' } | Select-Object ProcessId,ExecutablePath) | ConvertTo-Json -Compress",raw=(await exec('powershell.exe',['-NoProfile','-NonInteractive','-Command',command],{windowsHide:true,encoding:'utf8'})).stdout.trim(),parsed=raw?JSON.parse(raw):[],rows=Array.isArray(parsed)?parsed:[parsed];
